def moving_average(x, w):
    return np.convolve(x, np.ones(w), 'valid') / w

epochs = range(1, len(lr_train_loss) + 1)


plt.figure(figsize=(7, 7))

plt.plot(epochs, lr_train_loss, alpha=0.6, color= '#2D5AA9', linestyle='-', label="Train Loss")                                                                                                           
plt.plot(epochs, lr_val_loss, alpha=0.6, color= '#FF8C00', linestyle='--', label="Val Loss") 

w = 5
train_smooth = moving_average(lr_train_loss, w)
val_smooth = moving_average(lr_val_loss, w)
plt.plot(range(w, len(lr_train_loss)+1), train_smooth, color='#1A3F8C', linewidth=2.5, label="Train Loss (smoothed)")
plt.plot(range(w, len(lr_val_loss)+1), val_smooth, color='#D35400', linewidth=2.5, label="Val Loss (smoothed)")
plt.legend(loc='upper right', fontsize=18)
plt.xlabel('Epoch', fontsize=18)
plt.ylabel('Loss', fontsize=18)
plt.tick_params(axis='both', which='major', labelsize=16)
plt.tight_layout()
plt.savefig('abloss.pdf', dpi=600)


